#!/bin/bash
# Copies the paper assets (tables and figures generated by analysis/paper_assets.py) from the main checkout into
# paper/assets/, so the paper never reads results/ directly and never edits a table by hand. Run from anywhere:
#
#   bash paper/build_assets.sh            # MAIN_CHECKOUT: the checkout that holds results/
#
# MAIN_CHECKOUT defaults to the repository's main working tree, the parent of `git rev-parse --git-common-dir`: the
# repository root in a clone, the main checkout from a linked worktree (without git, the repository of this script).
#
# 1. Inputs of the assets: every row of each source folder's sources.tsv (path, SHA-256) is hashed again in the main
#    checkout; a mismatch stops the script (the assets are stale against their own inputs: regenerate them there).
# 2. The assets themselves: sources.tsv lists inputs, not the assets, so each copied asset's SHA-256 is recorded in
#    paper/assets/SHA256SUMS (asset, SHA-256, source path). A second run prints every asset whose hash changed since
#    the last copy, so a refresh shows exactly what moved.
# 3. Main-text tables: paper/tools/derive_tables.py writes row and column subsets of the frozen CSVs into
#    paper/assets/derived/ (cells copied verbatim, except regional price lists printed as ranges).
# 4. Appendix and supplement tables: paper/tools/relabel_tables.py writes copies with a fixed list of label
#    substitutions into paper/assets/relabeled/ (numbers unchanged; each substitution listed in the file header),
#    laid out for the supplement's 8 pt where too wide or too tall (paper/tools/table_layout.py; cells unchanged).
# Reads the main checkout only; writes under paper/assets/ only. macOS bash 3.2.
set -euo pipefail
PAPER="$(cd "$(dirname "$0")" && pwd)"
if [ -n "${MAIN_CHECKOUT:-}" ]; then
  MAIN=$MAIN_CHECKOUT
else
  MAIN=$(cd "$PAPER/.." && pwd)
  common=$(cd "$PAPER" && git rev-parse --git-common-dir 2> /dev/null) || common=""
  case "$common" in
    .git|*/.git) MAIN=$(cd "$PAPER" && cd "$common/.." && pwd) ;;
  esac
fi
# Source folders of the main checkout, each with its own sources.tsv and README.md:
#   results/paper_assets_followups34  analysis/paper_assets.py (main study, follow-ups 1 to 5)
#   results/paper_assets_fu678        analysis/paper_assets_fu678.py (follow-ups 6 to 8, analyses of 2026-11-02)
#   results/paper_assets_fu9          analysis/paper_assets_fu9.py (follow-up 9, analysis of 2026-11-04; tables only)
#   results/paper_assets_fu10_11_12   analysis/paper_assets_fu10_11_12.py (follow-ups 10, 11 and 12, analyses of
#                                     2026-11-08, 2026-11-06 and 2026-11-07; tables only)
#   results/paper_assets_isc          analysis/paper_assets_isc.py (the ISC paper's figures, tables, captions.tex and
#                                     campaign tables; read from the final freeze 4ec185c5, campaign counts scoped
#                                     to the 295 sessions of freeze 68923012); copied whole into
#                                     paper/assets/isc/ (tables/, figures/, captions.tex, README.md, sources.tsv)
# Tables and figures of all go to paper/assets/{tables,figures}/ (their names do not overlap: checked below); the
# README.md and sources.tsv of the later ones go to paper/assets/fu678/, fu9/ and fu10_11_12/.
SOURCES="results/paper_assets_followups34 results/paper_assets_fu678 results/paper_assets_fu9 results/paper_assets_fu10_11_12 results/paper_assets_isc"
DEST="$PAPER/assets"
sha() { shasum -a 256 "$1" | cut -d' ' -f1; }
for SRC_REL in $SOURCES; do
  [ -f "$MAIN/$SRC_REL/sources.tsv" ] || { echo "!! $MAIN/$SRC_REL/sources.tsv not found (MAIN_CHECKOUT=$MAIN)" >&2; exit 1; }
done

echo ">> 1. inputs of the assets"
for SRC_REL in $SOURCES; do
  bad=0 n=0
  while IFS=$'\t' read -r path want _; do
    [ "$path" = "path" ] && continue
    n=$((n + 1))
    case "$path" in
      "font: "*) file=${path#font: } ;;   # a system font the figures embed, recorded by absolute path
      *) file="$MAIN/$path" ;;
    esac
    if [ ! -f "$file" ]; then echo "   MISSING $path"; bad=$((bad + 1)); continue; fi
    got=$(sha "$file")
    [ "$got" = "$want" ] || { echo "   CHANGED $path"; bad=$((bad + 1)); }
  done < "$MAIN/$SRC_REL/sources.tsv"
  [ "$bad" -eq 0 ] || { echo "!! $SRC_REL: $bad of $n inputs differ from sources.tsv: regenerate the assets in the main checkout first" >&2; exit 1; }
  echo "   $SRC_REL/sources.tsv: $n of $n inputs match"
done
dup=$(for SRC_REL in $SOURCES; do [ "$SRC_REL" = results/paper_assets_isc ] && continue; (cd "$MAIN/$SRC_REL" && ls tables/*.tex tables/*.csv figures/*.pdf 2> /dev/null || true); done | sort | uniq -d)
[ -z "$dup" ] || { echo "!! asset names in more than one source folder: $dup" >&2; exit 1; }

echo ">> 2. copy"
mkdir -p "$DEST/tables" "$DEST/figures" "$DEST/derived" "$DEST/fu678" "$DEST/fu9" "$DEST/fu10_11_12" "$DEST/isc/tables" "$DEST/isc/figures"
OLD="$DEST/SHA256SUMS"
NEW="$DEST/SHA256SUMS.new"
: > "$NEW"
changed=0
for SRC_REL in $SOURCES; do
  SRC="$MAIN/$SRC_REL"
  case "$SRC_REL" in
    results/paper_assets_fu678) meta="fu678/" ;;
    results/paper_assets_fu9) meta="fu9/" ;;
    results/paper_assets_fu10_11_12) meta="fu10_11_12/" ;;
    results/paper_assets_isc) meta="isc/" ;;
    *) meta="" ;;
  esac
  pre=""; [ "$SRC_REL" = results/paper_assets_isc ] && pre="isc/"
  for f in "$SRC"/tables/*.tex "$SRC"/tables/*.csv "$SRC"/figures/*.pdf "$SRC/README.md" "$SRC/sources.tsv" "$SRC/captions.tex"; do
    [ -f "$f" ] || continue                           # a folder without figures: the glob stays unexpanded
    rel=${f#"$SRC"/}
    case "$rel" in README.md|sources.tsv|captions.tex) rel="$meta$rel" ;; *) rel="$pre$rel" ;; esac
    cp "$f" "$DEST/$rel"
    h=$(sha "$DEST/$rel")
    printf '%s\t%s\t%s\n' "$rel" "$h" "$SRC_REL/${f#"$SRC"/}" >> "$NEW"
    if [ -f "$OLD" ]; then
      prev=$(awk -F'\t' -v p="$rel" '$1 == p {print $2}' "$OLD")
      if [ "$prev" != "$h" ]; then
        if [ -n "$prev" ]; then echo "   changed $rel"; else echo "   new $rel"; fi
        changed=$((changed + 1))
      fi
    fi
  done
done
mv "$NEW" "$OLD"
echo "   $(wc -l < "$OLD" | tr -d ' ') files copied; ${changed} new or changed since the last copy (SHA256SUMS)"

echo ">> 3. derived main-text tables"
python3 "$PAPER/tools/derive_tables.py" "$DEST/tables" "$DEST/derived"
echo ">> 3b. center guides (supplement table and the counts the text cites)"
python3 "$PAPER/tools/center_guides.py" "$PAPER/research/center_guides.csv" "$DEST/derived"
echo ">> 4. relabeled tables (labels only: plan, \S11; the expected glycan gap)"
python3 "$PAPER/tools/relabel_tables.py" "$DEST/tables" "$DEST/relabeled"
